const lockNewsProcessing = `-- name: LockNewsProcessing :exec
SELECT pg_advisory_xact_lock($1::bigint)
`

// Serializes version processing across concurrent refreshes (a scheduled and
// an on-demand run): released when the transaction ends.
func (q *Queries) LockNewsProcessing(ctx context.Context, lockKey int64) error {
	_, err := q.db.Exec(ctx, lockNewsProcessing, lockKey)
	return err
}

