const upsertNewsArticle = `-- name: UpsertNewsArticle :one
INSERT INTO news_articles (publisher, external_id, source_id, kind, url, first_seen_at, last_seen_at, source_updated_at)
VALUES ($1, $2, $3, $4, $5, $6, $6, $7)
ON CONFLICT (publisher, external_id) DO UPDATE SET
    url = EXCLUDED.url,
    last_seen_at = GREATEST(news_articles.last_seen_at, EXCLUDED.last_seen_at),
    source_updated_at = COALESCE(EXCLUDED.source_updated_at, news_articles.source_updated_at)
RETURNING id
`

type UpsertNewsArticleParams struct {
	Publisher       string             `json:"publisher"`
	ExternalID      string             `json:"external_id"`
	SourceID        string             `json:"source_id"`
	Kind            string             `json:"kind"`
	Url             string             `json:"url"`
	FirstSeenAt     pgtype.Timestamptz `json:"first_seen_at"`
	SourceUpdatedAt pgtype.Timestamptz `json:"source_updated_at"`
}

func (q *Queries) UpsertNewsArticle(ctx context.Context, arg UpsertNewsArticleParams) (int64, error) {
	row := q.db.QueryRow(ctx, upsertNewsArticle,
		arg.Publisher,
		arg.ExternalID,
		arg.SourceID,
		arg.Kind,
		arg.Url,
		arg.FirstSeenAt,
		arg.SourceUpdatedAt,
	)
	var id int64
	err := row.Scan(&id)
	return id, err
}
